  'Color-Run': ['100 Shirts', '200 Shirts', '300 Shirts'],
  'Heat-Press': ['50 Shirts', '100 Shirts', '300 Shirts'],
  'Slime': ['24 Aprons', '50 Aprons', '100 Aprons'],
