export const DESIGN_PLACEMENT_CONFIG: { [key: string]: { [key: string]: string[] } } = {
    'T-Shirt': {
        'Front': ['Chest-Large', 'Left-Corner', 'Right-Corner', 'Chest-Letters Across'],
        'Sleeve': ['Right', 'Left', 'Both'],
        'Back': ['Small-Near Neck', 'Large-Middle'],
    },
    'Sweatshirts': {
        'Front': ['Chest-Large', 'Left-Corner', 'Right-Corner', 'Chest-Letters Across'],
        'Sleeve': ['Right', 'Left', 'Both'],
        'Back': ['Small-Near Neck', 'Large-Middle'],
    },
    'Hoodies': {
        'Front': ['Chest-Large', 'Left-Corner', 'Right-Corner', 'Chest-Letters Across'],
        'Sleeve': ['Right', 'Left', 'Both'],
