import React, { useMemo } from 'react';
import type { InquiryItem } from '../types';
import {
  CUSTOMIZATION_TYPES, PRODUCT_TYPES, OCCASIONS,
  WEARABLES_CATEGORIES, WEARABLES_STYLES
} from '../constants';
import { FormSection } from './FormSection';
import { CheckboxGroup } from './CheckboxGroup';
import { FormInput } from './FormInput';
import { SizeQuantityInput } from './SizeQuantityInput';
import { FileUpload } from './FileUpload';
import { DesignPlacementForm } from './DesignPlacementForm';

interface ItemFormProps {
  item: InquiryItem;
  index: number;
  onItemChange: (index: number, item: InquiryItem) => void;
  onRemoveItem: (index: number) => void;
  isOnlyItem: boolean;
}

export const ItemForm: React.FC<ItemFormProps> = ({ item, index, onItemChange, onRemoveItem, isOnlyItem }) => {
  const updateItem = (field: keyof InquiryItem, value: any) => {
    const newItem: InquiryItem = { ...item, [field]: value };

    // Reset downstream fields on change
    const resetFields: (keyof InquiryItem)[] = [];
    if (field === 'customizationType') {
        resetFields.push('productType', 'category', 'style', 'subStyle', 'finish', 'productQuality', 'productDetails', 'decorationMethod', 'color', 'knowsSizes', 'sizes', 'quantity', 'hasDesign', 'designFiles', 'occasion', 'occasionDetails', 'printingStyle', 'designDetails', 'designPlacement', 'designPlacementDetails');
    } else if (field === 'productType') {
        resetFields.push('category', 'style', 'subStyle', 'finish', 'productQuality', 'productDetails', 'decorationMethod', 'color', 'knowsSizes', 'sizes', 'quantity', 'hasDesign', 'designFiles', 'occasion', 'occasionDetails', 'printingStyle', 'designDetails', 'designPlacement', 'designPlacementDetails');
    } else if (field === 'category') {
        resetFields.push('style', 'subStyle', 'finish', 'knowsSizes', 'sizes', 'decorationMethod', 'designPlacement', 'designPlacementDetails');
    } else if (field === 'style') {
        resetFields.push('subStyle', 'finish', 'knowsSizes', 'sizes');
    }

    for (const f of resetFields) {
        if (f === 'sizes' || f === 'designPlacement') {
            (newItem as any)[f] = {};
        } else if (f === 'quantity') {
            (newItem as any)[f] = 0;
        } else if (f === 'designFiles' || f === 'occasion') {
            (newItem as any)[f] = [];
        } else {
            (newItem as any)[f] = '';
        }
    }
    onItemChange(index, newItem);
  };

  const totalQuantity = useMemo(() => {
    if (item.knowsSizes === 'Yes') {
      return (Object.values(item.sizes) as number[]).reduce((sum: number, qty: number) => sum + (qty || 0), 0);
    }
    return item.quantity;
  }, [item.sizes, item.quantity, item.knowsSizes]);

  let step = 1;

  const renderProductDetails = () => (
    <>
      <FormSection title="Select Category" step={step++}>
        <CheckboxGroup name={`cat-${item.id}`} options={WEARABLES_CATEGORIES} selectedValue={item.category} onChange={(v) => updateItem('category', v)} columns={4} />
      </FormSection>

      {item.category && item.category !== 'Other' && WEARABLES_STYLES[item.category] && (
        <FormSection title="Select Style" step={step++}>
          <CheckboxGroup name={`style-${item.id}`} options={WEARABLES_STYLES[item.category]} selectedValue={item.style} onChange={(v) => updateItem('style', v)} />
        </FormSection>
      )}

      {(item.category && (item.style || item.category === 'Other')) ? (
        <>
          <FormSection title="Product Quality" step={step++}>
            <CheckboxGroup name={`qual-${item.id}`} options={['Premium', 'Standard']} selectedValue={item.productQuality} onChange={(v) => updateItem('productQuality', v)} columns={2} />
            <label htmlFor={`prod-details-${item.id}`} className="block text-sm font-medium text-gray-700 mt-4 mb-1">Product Details (Optional)</label>
            <input id={`prod-details-${item.id}`} type="text" value={item.productDetails} onChange={(e) => updateItem('productDetails', e.target.value)} placeholder="Specific brand or product number" className="mt-1 block w-full px-4 py-2 bg-white border border-gray-300 rounded-md shadow-sm" />
          </FormSection>

          {item.productQuality && item.customizationType === 'CUSTOM' && (
            <FormSection title="Decoration Method" step={step++}>
              <CheckboxGroup name={`deco-${item.id}`} options={['Printing', 'Embroidery']} selectedValue={item.decorationMethod} onChange={(v) => updateItem('decorationMethod', v)} columns={2} />
            </FormSection>
          )}

          {(item.productQuality && (item.customizationType === 'BLANK' || item.decorationMethod)) && (
            <>
              <FormSection title="Color" step={step++}>
                <FormInput name={`color-${item.id}`} label="Product Color" value={item.color} onChange={(e) => updateItem('color', e.target.value)} placeholder="e.g., Navy Blue, Heather Grey" />
              </FormSection>

              {item.color && (
                <FormSection title="Do you know which sizes you need?" step={step++}>
                  <CheckboxGroup name={`knows-sizes-${item.id}`} options={['Yes', 'No']} selectedValue={item.knowsSizes} onChange={(v) => updateItem('knowsSizes', v)} columns={2} />
                </FormSection>
              )}

              {item.knowsSizes === 'No' && (
                <FormSection title="Total Quantity" step={step++}>
                  <FormInput name={`quantity-${item.id}`} label="Enter total quantity" type="number" value={item.quantity} onChange={(e) => updateItem('quantity', parseInt(e.target.value) || 0)} />
                </FormSection>
              )}

              {item.knowsSizes === 'Yes' && (
                <FormSection title="Sizes & Quantities" step={step++}>
                  <SizeQuantityInput
                    category={item.category}
                    style={item.style}
                    sizes={item.sizes}
                    onSizeChange={(sizes) => updateItem('sizes', sizes)}
                  />
                  <div className="mt-4 text-right font-bold text-lg text-indigo-600">Total Quantity: {totalQuantity}</div>
                </FormSection>
              )}
            </>
          )}
        </>
      ) : null}
    </>
  );

  const isCustom = item.customizationType === 'CUSTOM';
  const showDesignUpload = isCustom && totalQuantity > 0;
  const showFinalQuestions = totalQuantity > 0;

  return (
    <div className="bg-white p-8 rounded-2xl shadow-lg border border-gray-200 relative">
      <div className="flex justify-between items-start mb-6">
        <h3 className="text-2xl font-bold text-gray-800">Item #{index + 1}</h3>
        {!isOnlyItem && (
          <button type="button" onClick={() => onRemoveItem(index)} className="text-red-500 hover:text-red-700 transition">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" />
            </svg>
          </button>
        )}
      </div>

      <div className="space-y-6">
        <FormSection title="Select Product Type" step={step++}>
          <CheckboxGroup name={`custom-type-${item.id}`} options={CUSTOMIZATION_TYPES} selectedValue={item.customizationType} onChange={(v) => updateItem('customizationType', v)} columns={2} />
        </FormSection>

        {item.customizationType && (
          <FormSection title="Select Color" step={step++}>
            <CheckboxGroup 
              name={`prod-type-${item.id}`} 
              options={PRODUCT_TYPES} 
              selectedValue={item.productType} 
              onChange={(v) => updateItem('productType', v)} 
              columns={2}
            />
          </FormSection>
        )}

        {(item.productType === 'Black' || item.productType === 'Brown') && renderProductDetails()}

        {showDesignUpload && (
          <FormSection title="Do you have a design?" step={step++}>
            <CheckboxGroup name={`has-design-${item.id}`} options={['Yes', 'No']} selectedValue={item.hasDesign} onChange={(v) => updateItem('hasDesign', v)} columns={2} />

            {item.hasDesign === 'Yes' && (
              <div className="mt-4">
                  <label className="block text-sm font-medium text-gray-700 mb-1">Upload Your Design</label>
                  <FileUpload maxFiles={4} onFilesChange={(files) => updateItem('designFiles', files)} />
              </div>
            )}
            {item.hasDesign === 'No' && (
              <div className="mt-4">
                  <label className="block text-sm font-medium text-gray-700 mb-1">Upload Ideas or Inspiration</label>
                  <FileUpload maxFiles={4} onFilesChange={(files) => updateItem('designFiles', files)} />
              </div>
            )}

            {item.hasDesign && (
              <div className="mt-4">
                  <label htmlFor={`design-details-${item.id}`} className="block text-sm font-medium text-gray-700 mb-1">
                      Design Details
                  </label>
                  <textarea
                      id={`design-details-${item.id}`}
                      value={item.designDetails}
                      onChange={(e) => updateItem('designDetails', e.target.value)}
                      rows={3}
                      placeholder="Describe your design, colors, text, etc."
                      className="mt-1 block w-full px-4 py-2 bg-white border border-gray-300 rounded-md shadow-sm"
                  />
              </div>
            )}
          </FormSection>
        )}

        {item.hasDesign && isCustom && (
          <FormSection title="Where would you like your design?" step={step++}>
            <DesignPlacementForm
              category={item.category}
              placement={item.designPlacement}
              details={item.designPlacementDetails}
              onPlacementChange={(p) => updateItem('designPlacement', p)}
              onDetailsChange={(d) => updateItem('designPlacementDetails', d)}
              itemId={item.id}
            />
          </FormSection>
        )}

        {showFinalQuestions && (
          <>
            <FormSection title="What's the Occasion?" step={step++}>
              <CheckboxGroup type="checkbox" name={`occasion-${item.id}`} options={OCCASIONS} selectedValue={item.occasion} onChange={(v) => {
                  const newOccasions = item.occasion.includes(v) ? item.occasion.filter(o => o !== v) : [...item.occasion, v];
                  updateItem('occasion', newOccasions);
              }} columns={4} />
              <div className="mt-4">
                <label htmlFor={`occasion-details-${item.id}`} className="block text-sm font-medium text-gray-700 mb-1">
                    More information about the occasion (Optional)
                </label>
                <textarea
                    id={`occasion-details-${item.id}`}
                    value={item.occasionDetails}
                    onChange={(e) => updateItem('occasionDetails', e.target.value)}
                    rows={3}
                    placeholder="If you selected 'Other' or want to provide more context, please do so here."
                    className="mt-1 block w-full px-4 py-2 bg-white border border-gray-300 rounded-md shadow-sm placeholder-gray-400 focus:outline-none focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm transition-all"
                />
              </div>
            </FormSection>

            <FormSection title="Event Information" step={step++}>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">Due Date</label>
                  <input type="date" value={item.dueDate} onChange={(e) => updateItem('dueDate', e.target.value)} className="mt-1 block w-full px-4 py-2 bg-white border border-gray-300 rounded-md shadow-sm" />
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">Is this date flexible?</label>
                  <CheckboxGroup name={`flexible-date-${item.id}`} options={['Yes', 'No']} selectedValue={item.isDateFlexible} onChange={(v) => updateItem('isDateFlexible', v)} columns={2} />
                </div>
              </div>
            </FormSection>

            <FormSection title="Additional Notes" step={step++}>
                <textarea
                    value={item.additionalNotes}
                    onChange={(e) => updateItem('additionalNotes', e.target.value)}
                    rows={4}
                    placeholder="Anything else we should know?"
                    className="mt-1 block w-full px-4 py-2 bg-white border border-gray-300 rounded-md shadow-sm"
                />
            </FormSection>
          </>
        )}
      </div>
    </div>
  );
};

import React, { useState, useCallback } from 'react';
import type { CustomerInfo, InquiryItem } from './types';
import { ItemForm } from './components/ItemForm';
import { FormInput } from './components/FormInput';
import { Header } from './components/Header';
import { initialInquiryItem, initialCustomerInfo } from './constants';

/**
 * Formats the inquiry data into a readable string for an email body.
 */
const formatInquiryForEmail = (customerInfo: CustomerInfo, items: InquiryItem[]): string => {
    let summary = `New Order Inquiry\n\n`;
    summary += `== Customer Information ==\n`;
    summary += `Name: ${customerInfo.name}\n`;
    summary += `Email: ${customerInfo.email}\n`;
    summary += `Phone: ${customerInfo.phone || 'N/A'}\n`;
    summary += `Organization: ${customerInfo.organization}\n\n`;

    items.forEach((item, index) => {
        summary += `== Item #${index + 1} ==\n`;
        // Label mapped to 'Product Type' in UI
        summary += `Product Type: ${item.customizationType}\n`;
        // Label mapped to 'Color' in UI
        summary += `Color: ${item.productType}\n`;
        if (item.category) summary += `Category: ${item.category}\n`;
        if (item.style) summary += `Style: ${item.style}\n`;
        if (item.subStyle) summary += `Sub-Style/Type: ${item.subStyle}\n`;
        if (item.finish) summary += `Finish: ${item.finish}\n`;
        if (item.productQuality) summary += `Product Quality: ${item.productQuality}\n`;
        if (item.productDetails) summary += `Product Details: ${item.productDetails}\n`;
        if (item.decorationMethod) summary += `Decoration Method: ${item.decorationMethod}\n`;
        if (item.color) summary += `Color Details: ${item.color}\n`;
        if (item.printingStyle) summary += `Printing Style: ${item.printingStyle}\n`;
        if (item.ruling) summary += `Ruling: ${item.ruling}\n`;

        let total = 0;
        if (item.knowsSizes === 'No') {
            total = item.quantity;
        } else if (item.knowsSizes === 'Yes') {
            total = (Object.values(item.sizes) as number[]).reduce((sum, qty) => sum + (qty || 0), 0);
            summary += `Sizes & Quantities:\n`;
            Object.entries(item.sizes).forEach(([size, qty]) => {
                if (Number(qty) > 0) {
                    summary += `  - ${size}: ${qty}\n`;
                }
            });
        }

        if (total > 0 || ((item.productType === 'Black' || item.productType === 'Brown') && item.knowsSizes === 'Yes')) {
           summary += `Total Quantity: ${total}\n`;
        }

        if (item.hasDesign) {
            summary += `Has Design: ${item.hasDesign}\n`;
            summary += `Design Details: ${item.designDetails || 'N/A'}\n`;
            summary += `Uploaded Files: ${item.designFiles.length} file(s) will be attached.\n`;
        }

        if ((item.productType === 'Black' || item.productType === 'Brown') && Object.keys(item.designPlacement).length > 0) {
            summary += `Design Placement:\n`;
            Object.entries(item.designPlacement).forEach(([location, placements]) => {
                if (Array.isArray(placements) && placements.length > 0) {
                    summary += `  - ${location}: ${placements.join(', ')}\n`;
                }
            });
            if (item.designPlacementDetails) {
                 summary += `Placement Details: ${item.designPlacementDetails}\n`;
            }
        }

        if (item.occasion.length > 0) summary += `Occasion: ${item.occasion.join(', ')}\n`;
        if (item.occasionDetails) summary += `Occasion Details: ${item.occasionDetails}\n`;
        if (item.dueDate) summary += `Due Date: ${item.dueDate}\n`;
        if (item.isDateFlexible) summary += `Date Flexible: ${item.isDateFlexible}\n`;
        if (item.additionalNotes) summary += `Additional Notes: ${item.additionalNotes}\n`;

        summary += `\n`;
    });

    return summary;
};


const App: React.FC = () => {
  const [customerInfo, setCustomerInfo] = useState<CustomerInfo>(initialCustomerInfo);
  const [items, setItems] = useState<InquiryItem[]>([initialInquiryItem]);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [submitStatus, setSubmitStatus] = useState<'success' | 'error' | null>(null);

  const handleCustomerInfoChange = useCallback((e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    setCustomerInfo(prev => ({ ...prev, [name]: value }));
  }, []);

  const handleItemChange = useCallback((index: number, updatedItem: InquiryItem) => {
    setItems(prevItems => {
      const newItems = [...prevItems];
      newItems[index] = updatedItem;
      return newItems;
    });
  }, []);

  const handleRemoveItem = useCallback((index: number) => {
    setItems(prevItems => prevItems.filter((_, i) => i !== index));
  }, []);

  const handleAddItem = () => {
    setItems(prevItems => [...prevItems, { ...initialInquiryItem, id: Date.now() }]);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSubmitting(true);
    setSubmitStatus(null);

    const formData = new FormData();
    formData.append('_replyto', customerInfo.email);
    formData.append('_subject', `New Inquiry from ${customerInfo.name} - ${customerInfo.organization}`);
    const emailSummary = formatInquiryForEmail(customerInfo, items);
    formData.append('Inquiry Summary', emailSummary);

    items.forEach((item, itemIndex) => {
        item.designFiles.forEach((file, fileIndex) => {
            formData.append(`item_${itemIndex + 1}_file_${fileIndex + 1}`, file);
        });
    });

    try {
      const response = await fetch('https://formspree.io/f/YOUR_FORM_ID_HERE', {
        method: 'POST',
        body: formData,
        headers: {
          'Accept': 'application/json'
        }
      });

      if (response.ok) {
        setSubmitStatus('success');
        setItems([{ ...initialInquiryItem, id: Date.now() }]);
        setCustomerInfo(initialCustomerInfo);
      } else {
        throw new Error('Form submission failed. Please try again.');
      }
    } catch (error) {
      console.error(error);
      setSubmitStatus('error');
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <div className="min-h-screen bg-gray-50 text-gray-800 font-sans">
      <div className="container mx-auto p-4 sm:p-6 lg:p-8">
        <Header />
        <form onSubmit={handleSubmit} className="mt-8 space-y-12">
          <div className="bg-white p-8 rounded-2xl shadow-lg border border-gray-200">
            <h2 className="text-3xl font-bold text-gray-800 border-b pb-4 mb-6">Contact Information</h2>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-x-8 gap-y-6">
              <FormInput
                label="Name"
                name="name"
                value={customerInfo.name}
                onChange={handleCustomerInfoChange}
                required
              />
              <FormInput
                label="Email"
                name="email"
                type="email"
                value={customerInfo.email}
                onChange={handleCustomerInfoChange}
                required
              />
              <FormInput
                label="Phone Number"
                name="phone"
                type="tel"
                value={customerInfo.phone}
                onChange={handleCustomerInfoChange}
              />
              <FormInput
                label="Organization or Site"
                name="organization"
                value={customerInfo.organization}
                onChange={handleCustomerInfoChange}
                required
              />
            </div>
          </div>

          {items.map((item, index) => (
            <ItemForm
              key={item.id}
              item={item}
              index={index}
              onItemChange={handleItemChange}
              onRemoveItem={handleRemoveItem}
              isOnlyItem={items.length === 1}
            />
          ))}

          <div className="flex flex-col sm:flex-row justify-between items-center gap-4 pt-6 border-t">
            <button
              type="button"
              onClick={handleAddItem}
              className="w-full sm:w-auto flex items-center justify-center gap-2 px-6 py-3 text-base font-semibold text-indigo-600 bg-indigo-100 rounded-lg hover:bg-indigo-200 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-indigo-500 transition-all duration-200"
            >
              <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor">
                <path fillRule="evenodd" d="M10 3a1 1 0 011 1v5h5a1 1 0 110 2h-5v5a1 1 0 11-2 0v-5H4a1 1 0 110-2h5V4a1 1 0 011-1z" clipRule="evenodd" />
              </svg>
              Add Another Item
            </button>
            <button
              type="submit"
              disabled={isSubmitting}
              className="w-full sm:w-auto px-10 py-3 text-base font-semibold text-white bg-indigo-600 rounded-lg hover:bg-indigo-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-indigo-500 transition-all duration-200 shadow-md disabled:bg-indigo-400 disabled:cursor-not-allowed"
            >
              {isSubmitting ? 'Submitting...' : 'Submit Inquiry'}
            </button>
          </div>
        </form>

        {submitStatus === 'success' && (
          <div className="mt-8 p-4 bg-green-100 border border-green-400 text-green-800 rounded-lg shadow-md" role="alert">
            <strong className="font-bold">Thank You! </strong>
            <span className="block sm:inline">Your inquiry has been submitted successfully. We will get back to you shortly.</span>
          </div>
        )}
        {submitStatus === 'error' && (
          <div className="mt-8 p-4 bg-red-100 border border-red-400 text-red-800 rounded-lg shadow-md" role="alert">
            <strong className="font-bold">Submission Error! </strong>
            <span className="block sm:inline">Something went wrong. Please check your connection and try again.</span>
          </div>
        )}

        <footer className="text-center mt-12 py-6 border-t border-gray-200">
          <p className="text-gray-600">
            Thank you for submitting your Inquiry! For more information please contact{' '}
            <a href="mailto:contact@dividedattentionclothing.com" className="text-indigo-600 hover:underline font-medium">
              contact@dividedattentionclothing.com
            </a>
          </p>
        </footer>
      </div>
    </div>
  );
};

export default App;

import React, { useMemo } from 'react';
import type { InquiryItem } from '../types';
import {
  CUSTOMIZATION_TYPES, PRODUCT_TYPES, OCCASIONS,
  WEARABLES_CATEGORIES, WEARABLES_STYLES
} from '../constants';
import { FormSection } from './FormSection';
import { CheckboxGroup } from './CheckboxGroup';
import { FormInput } from './FormInput';
import { SizeQuantityInput } from './SizeQuantityInput';
import { FileUpload } from './FileUpload';
import { DesignPlacementForm } from './DesignPlacementForm';

interface ItemFormProps {
  item: InquiryItem;
  index: number;
  onItemChange: (index: number, item: InquiryItem) => void;
  onRemoveItem: (index: number) => void;
  isOnlyItem: boolean;
}

export const ItemForm: React.FC<ItemFormProps> = ({ item, index, onItemChange, onRemoveItem, isOnlyItem }) => {
  const updateItem = (field: keyof InquiryItem, value: any) => {
    const newItem: InquiryItem = { ...item, [field]: value };

    // Reset downstream fields on change
    const resetFields: (keyof InquiryItem)[] = [];
    if (field === 'customizationType') {
        resetFields.push('productType', 'category', 'style', 'subStyle', 'finish', 'productQuality', 'productDetails', 'decorationMethod', 'color', 'knowsSizes', 'sizes', 'quantity', 'hasDesign', 'designFiles', 'occasion', 'occasionDetails', 'printingStyle', 'designDetails', 'designPlacement', 'designPlacementDetails');
    } else if (field === 'productType') {
        resetFields.push('category', 'style', 'subStyle', 'finish', 'productQuality', 'productDetails', 'decorationMethod', 'color', 'knowsSizes', 'sizes', 'quantity', 'hasDesign', 'designFiles', 'occasion', 'occasionDetails', 'printingStyle', 'designDetails', 'designPlacement', 'designPlacementDetails');
    } else if (field === 'category') {
        resetFields.push('style', 'subStyle', 'finish', 'knowsSizes', 'sizes', 'decorationMethod', 'designPlacement', 'designPlacementDetails');
    } else if (field === 'style') {
        resetFields.push('subStyle', 'finish', 'knowsSizes', 'sizes');
    }

    for (const f of resetFields) {
        if (f === 'sizes' || f === 'designPlacement') {
            (newItem as any)[f] = {};
        } else if (f === 'quantity') {
            (newItem as any)[f] = 0;
        } else if (f === 'designFiles' || f === 'occasion') {
            (newItem as any)[f] = [];
        } else {
            (newItem as any)[f] = '';
        }
    }
    onItemChange(index, newItem);
  };

  const totalQuantity = useMemo(() => {
    if (item.knowsSizes === 'Yes') {
      return (Object.values(item.sizes) as number[]).reduce((sum: number, qty: number) => sum + (qty || 0), 0);
    }
    return item.quantity;
  }, [item.sizes, item.quantity, item.knowsSizes]);

  let step = 1;

  const renderProductDetails = () => (
    <>
      <FormSection title="Select Category" step={step++}>
        <CheckboxGroup name={`cat-${item.id}`} options={WEARABLES_CATEGORIES} selectedValue={item.category} onChange={(v) => updateItem('category', v)} columns={4} />
      </FormSection>

      {item.category && item.category !== 'Other' && WEARABLES_STYLES[item.category] && (
        <FormSection title="Select Style" step={step++}>
          <CheckboxGroup name={`style-${item.id}`} options={WEARABLES_STYLES[item.category]} selectedValue={item.style} onChange={(v) => updateItem('style', v)} />
        </FormSection>
      )}

      {(item.category && (item.style || item.category === 'Other')) ? (
        <>
          <FormSection title="Product Quality" step={step++}>
            <CheckboxGroup name={`qual-${item.id}`} options={['Premium', 'Standard']} selectedValue={item.productQuality} onChange={(v) => updateItem('productQuality', v)} columns={2} />
            <label htmlFor={`prod-details-${item.id}`} className="block text-sm font-medium text-gray-700 mt-4 mb-1">Product Details (Optional)</label>
            <input id={`prod-details-${item.id}`} type="text" value={item.productDetails} onChange={(e) => updateItem('productDetails', e.target.value)} placeholder="Specific brand or product number" className="mt-1 block w-full px-4 py-2 bg-white border border-gray-300 rounded-md shadow-sm" />
          </FormSection>

          {item.productQuality && (
            <>
              <FormSection title="Color" step={step++}>
                <FormInput name={`color-${item.id}`} label="Product Color" value={item.color} onChange={(e) => updateItem('color', e.target.value)} placeholder="e.g., Navy Blue, Heather Grey" />
              </FormSection>

              {item.color && (
                <FormSection title="Do you know which sizes you need?" step={step++}>
                  <CheckboxGroup name={`knows-sizes-${item.id}`} options={['Yes', 'No']} selectedValue={item.knowsSizes} onChange={(v) => updateItem('knowsSizes', v)} columns={2} />
                </FormSection>
              )}

              {item.knowsSizes === 'No' && (
                <FormSection title="Total Quantity" step={step++}>
                  <FormInput name={`quantity-${item.id}`} label="Enter total quantity" type="number" value={item.quantity} onChange={(e) => updateItem('quantity', parseInt(e.target.value) || 0)} />
                </FormSection>
              )}

              {item.knowsSizes === 'Yes' && (
                <FormSection title="Sizes & Quantities" step={step++}>
                  <SizeQuantityInput
                    category={item.category}
                    style={item.style}
                    sizes={item.sizes}
                    onSizeChange={(sizes) => updateItem('sizes', sizes)}
                  />
                  <div className="mt-4 text-right font-bold text-lg text-indigo-600">Total Quantity: {totalQuantity}</div>
                </FormSection>
              )}

              {/* Decoration Method: Moved here to appear after quantity for CUSTOM items */}
              {item.customizationType === 'CUSTOM' && totalQuantity > 0 && (
                <FormSection title="Decoration Method" step={step++}>
                  <CheckboxGroup name={`deco-${item.id}`} options={['Printing', 'Embroidery']} selectedValue={item.decorationMethod} onChange={(v) => updateItem('decorationMethod', v)} columns={2} />
                </FormSection>
              )}
            </>
          )}
        </>
      ) : null}
    </>
  );

  const isCustom = item.customizationType === 'CUSTOM';
  const showDesignUpload = isCustom && totalQuantity > 0 && item.decorationMethod;
  const showFinalQuestions = totalQuantity > 0 && (item.customizationType === 'BLANK' || item.decorationMethod);

  return (
    <div className="bg-white p-8 rounded-2xl shadow-lg border border-gray-200 relative">
      <div className="flex justify-between items-start mb-6">
        <h3 className="text-2xl font-bold text-gray-800">Item #{index + 1}</h3>
        {!isOnlyItem && (
          <button type="button" onClick={() => onRemoveItem(index)} className="text-red-500 hover:text-red-700 transition">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" />
            </svg>
          </button>
        )}
      </div>

      <div className="space-y-6">
        <FormSection title="Select Product Type" step={step++}>
          <CheckboxGroup name={`custom-type-${item.id}`} options={CUSTOMIZATION_TYPES} selectedValue={item.customizationType} onChange={(v) => updateItem('customizationType', v)} columns={2} />
        </FormSection>

        {item.customizationType && (
          <FormSection title="Select Color" step={step++}>
            <CheckboxGroup 
              name={`prod-type-${item.id}`} 
              options={PRODUCT_TYPES} 
              selectedValue={item.productType} 
              onChange={(v) => updateItem('productType', v)} 
              columns={2}
            />
          </FormSection>
        )}

        {(item.productType === 'Black' || item.productType === 'Brown') && renderProductDetails()}

        {showDesignUpload && (
          <FormSection title="Do you have a design?" step={step++}>
            <CheckboxGroup name={`has-design-${item.id}`} options={['Yes', 'No']} selectedValue={item.hasDesign} onChange={(v) => updateItem('hasDesign', v)} columns={2} />

            {item.hasDesign === 'Yes' && (
              <div className="mt-4">
                  <label className="block text-sm font-medium text-gray-700 mb-1">Upload Your Design</label>
                  <FileUpload maxFiles={4} onFilesChange={(files) => updateItem('designFiles', files)} />
              </div>
            )}
            {item.hasDesign === 'No' && (
              <div className="mt-4">
                  <label className="block text-sm font-medium text-gray-700 mb-1">Upload Ideas or Inspiration</label>
                  <FileUpload maxFiles={4} onFilesChange={(files) => updateItem('designFiles', files)} />
              </div>
            )}

            {item.hasDesign && (
              <div className="mt-4">
                  <label htmlFor={`design-details-${item.id}`} className="block text-sm font-medium text-gray-700 mb-1">
                      Design Details
                  </label>
                  <textarea
                      id={`design-details-${item.id}`}
                      value={item.designDetails}
                      onChange={(e) => updateItem('designDetails', e.target.value)}
                      rows={3}
                      placeholder="Describe your design, colors, text, etc."
                      className="mt-1 block w-full px-4 py-2 bg-white border border-gray-300 rounded-md shadow-sm"
                  />
              </div>
            )}
          </FormSection>
        )}

        {item.hasDesign && isCustom && (
          <FormSection title="Where would you like your design?" step={step++}>
            <DesignPlacementForm
              category={item.category}
              placement={item.designPlacement}
              details={item.designPlacementDetails}
              onPlacementChange={(p) => updateItem('designPlacement', p)}
              onDetailsChange={(d) => updateItem('designPlacementDetails', d)}
              itemId={item.id}
            />
          </FormSection>
        )}

        {showFinalQuestions && (
          <>
            <FormSection title="What's the Occasion?" step={step++}>
              <CheckboxGroup type="checkbox" name={`occasion-${item.id}`} options={OCCASIONS} selectedValue={item.occasion} onChange={(v) => {
                  const newOccasions = item.occasion.includes(v) ? item.occasion.filter(o => o !== v) : [...item.occasion, v];
                  updateItem('occasion', newOccasions);
              }} columns={4} />
              <div className="mt-4">
                <label htmlFor={`occasion-details-${item.id}`} className="block text-sm font-medium text-gray-700 mb-1">
                    More information about the occasion (Optional)
                </label>
                <textarea
                    id={`occasion-details-${item.id}`}
                    value={item.occasionDetails}
                    onChange={(e) => updateItem('occasionDetails', e.target.value)}
                    rows={3}
                    placeholder="If you selected 'Other' or want to provide more context, please do so here."
                    className="mt-1 block w-full px-4 py-2 bg-white border border-gray-300 rounded-md shadow-sm placeholder-gray-400 focus:outline-none focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm transition-all"
                />
              </div>
            </FormSection>

            <FormSection title="Event Information" step={step++}>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">Due Date</label>
                  <input type="date" value={item.dueDate} onChange={(e) => updateItem('dueDate', e.target.value)} className="mt-1 block w-full px-4 py-2 bg-white border border-gray-300 rounded-md shadow-sm" />
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-1">Is this date flexible?</label>
                  <CheckboxGroup name={`flexible-date-${item.id}`} options={['Yes', 'No']} selectedValue={item.isDateFlexible} onChange={(v) => updateItem('isDateFlexible', v)} columns={2} />
                </div>
              </div>
            </FormSection>

            <FormSection title="Additional Notes" step={step++}>
                <textarea
                    value={item.additionalNotes}
                    onChange={(e) => updateItem('additionalNotes', e.target.value)}
                    rows={4}
                    placeholder="Anything else we should know?"
                    className="mt-1 block w-full px-4 py-2 bg-white border border-gray-300 rounded-md shadow-sm"
                />
            </FormSection>
          </>
        )}
      </div>
    </div>
  );
};

