import React from 'react';
import type { DesignPlacement } from '../types';
import { DESIGN_PLACEMENT_CONFIG } from '../constants';
import { CheckboxGroup } from './CheckboxGroup';

interface DesignPlacementFormProps {
  category: string;
  placement: DesignPlacement;
  details: string;
  onPlacementChange: (placement: DesignPlacement) => void;
  onDetailsChange: (details: string) => void;
  itemId: number;
}

export const DesignPlacementForm: React.FC<DesignPlacementFormProps> = ({
  category,
  placement,
  details,
  onPlacementChange,
  onDetailsChange,
  itemId,
}) => {
  const config = DESIGN_PLACEMENT_CONFIG[category];

  const handleSelectionChange = (location: string, option: string) => {
    const currentLocationSelection = placement[location] || [];
    const newSelection = currentLocationSelection.includes(option)
      ? currentLocationSelection.filter(o => o !== option)
      : [...currentLocationSelection, option];
    onPlacementChange({ ...placement, [location]: newSelection });
  };

  return (
    <div className="space-y-6">
      {config && Object.entries(config).map(([location, options]) => (
        <div key={location}>
          <h4 className="text-md font-semibold text-gray-600 mb-3">{location}</h4>
          <CheckboxGroup
            type="checkbox"
            name={`placement-${itemId}-${location}`}
            options={options}
            selectedValue={placement[location] || []}
            onChange={(option) => handleSelectionChange(location, option)}
            columns={4}
          />
        </div>
      ))}
      <div>
        <label htmlFor={`placement-details-${itemId}`} className="block text-sm font-medium text-gray-700 mt-4 mb-1">
          Placement Details
        </label>
        <textarea
          id={`placement-details-${itemId}`}
          value={details}
          onChange={(e) => onDetailsChange(e.target.value)}
          rows={3}
          placeholder="e.g., Place the logo 2 inches below the collar on the left chest."
          className="mt-1 block w-full px-4 py-2 bg-white border border-gray-300 rounded-md shadow-sm placeholder-gray-400 focus:outline-none focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm transition-all"
        />
      </div>
    </div>
  );
};

